insert into public.prephub_outreach_scripts(script_key,version,title,channel,content,approved_at,approved_by) values ('call_disconnect_recovery',1,'Daisy — reconnect after a dropped call','email','{"subject":"Let’s pick up where we left off","body":"Hi {first_name},\n\nIt looks like our call was disconnected, and we weren’t able to stay connected when I called back.\n\nWhen you have a steady connection and a few minutes, please call us at 1-833-302-8953 so we can pick up where we left off with your homebuyer preparation.\n\nYou can also return to PrepHub anytime to review your checklist and save your progress:\nhttps://www.dpahelpcenter.com/prephub/\n\nI look forward to working with you.\n\nDaisy\nYour PrepHub first-time homebuyer preparation assistant\nDPA Help Center","cta":"Call DPA Help Center","callback_phone":"1-833-302-8953"}'::jsonb,now(),(select user_id from manager_members where role='owner' and active=true order by user_id limit 1)) on conflict(script_key,version) do nothing returning id,script_key,title,version,channel;
